/* =========================================================
UTILITIES
========================================================= */
const fmt = n => new Intl.NumberFormat(STATE.lang === 'en' ? 'en-US' : 'ar-EG',{style:'currency',currency:'EGP',maximumFractionDigits:0}).format(n);
const t = k => (I18N[STATE.lang] && I18N[STATE.lang][k]) || k;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

function applyI18n(){
document.documentElement.lang = STATE.lang;
document.documentElement.dir = STATE.lang==='ar' ? 'rtl' : 'ltr';
const langLabel = document.getElementById('langLabel');
if(langLabel) langLabel.textContent = STATE.lang==='ar' ? 'EN' : 'AR';
document.querySelectorAll('[data-i18n]').forEach(el=>{
const k = el.getAttribute('data-i18n');
if(k==='hero_title'){ el.innerHTML = t('hero_title_html'); return; }
const v = t(k);
if(v) el.textContent = v;
});
document.querySelectorAll('[data-i18n-ph]').forEach(el=>{
el.placeholder = t(el.getAttribute('data-i18n-ph'));
});
window.PlatformLanguage?.setDictionary(PUBLIC_TEXT_TRANSLATIONS);
window.PlatformLanguage?.apply(document, STATE.lang, PUBLIC_TEXT_TRANSLATIONS);
}

function toast(msg, type='info'){
const wrap = document.getElementById('toastWrap');
if(!wrap) return;
const el = document.createElement('div');
el.className = `toast toast-${type}`;
const iconSuccess = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><path d="M22 4L12 14.01l-3-3"/></svg>';
const iconError = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></svg>';
const iconInfo = '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="10"/><path d="M12 16v-4M12 8h.01"/></svg>';
const icon = type==='success' ? iconSuccess : type==='error' ? iconError : iconInfo;
el.innerHTML = `<div class="toast-icon">${icon}</div><div class="toast-msg">${esc(msg)}</div>`;
wrap.appendChild(el);
setTimeout(()=>{el.style.opacity='0';el.style.transform='translateX(30px)';setTimeout(()=>el.remove(),300)},3200);
}

function toggleLang(){
STATE.lang = STATE.lang==='ar' ? 'en' : 'ar';
localStorage.setItem('nbc_lang', STATE.lang);
window.PlatformLanguage?.setLanguage(STATE.lang, true);
applyI18n();
renderAll();
}

window.addEventListener('platform:languagechange', event => {
  const next = event.detail === 'en' ? 'en' : 'ar';
  if (STATE.lang === next) return;
  STATE.lang = next;
  applyI18n();
  renderAll();
});

function toggleMobileNav(){
const mobileNav = document.getElementById('mobileNav');
if(mobileNav) mobileNav.classList.toggle('open');
}

/* =========================================================
ROUTING
========================================================= */
function navigate(route, params={}){
if(route === 'login'){ window.location.href = 'auth/login.php'; return; }
if(route === 'register'){ window.location.href = 'auth/register.php'; return; }
if(route === 'instructor-dash'){ window.location.href = 'instructor.html'; return; }
if(route === 'admin-dash'){ window.location.href = 'admin.html'; return; }
STATE.currentRoute = route;
if(params.id){ STATE.currentDetailId = params.id; STATE.currentDetailType = params.type; }
document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
const page = document.getElementById('page-'+route);
const activePage = page || document.getElementById('page-home');
if(activePage){activePage.classList.add('active');activePage.classList.remove('platform-page-enter');void activePage.offsetWidth;activePage.classList.add('platform-page-enter');setTimeout(()=>activePage.classList.remove('platform-page-enter'),520);}
if(!page) STATE.currentRoute='home';
document.querySelectorAll('.nav-link').forEach(a=>{
a.classList.toggle('active', a.dataset.route === STATE.currentRoute);
});
if(route==='courses') renderCourses();
if(route==='books') renderBooks();
if(route==='offers') renderOffers();
if(route==='instructors') renderInstructors();
if(route==='course-detail') renderCourseDetail();
if(route==='book-detail') renderBookDetail();
if(route==='cart') renderCart();
if(route==='checkout') renderCheckout();
if(route==='student-dash') { window.location.href = 'student.html'; return; }
if(route==='instructor-dash') { window.location.href = 'instructor.html'; return; }
if(route==='admin-dash') { window.location.href = 'admin.html'; return; }
if(route==='contact'){ renderFAQ('faqList2'); }
const mobileNav = document.getElementById('mobileNav');
if(mobileNav) mobileNav.classList.remove('open');
window.scrollTo({top:0,behavior:'smooth'});
history.replaceState(null, '', '#' + STATE.currentRoute);
}

