function centerWhatsAppLink(center, message = '') {
  const raw = String(center.whatsapp || center.phone || (STATE.settings && STATE.settings.contactPhone) || '01289492477').replace(/\D/g, '');
  const phone = raw.startsWith('20') ? raw : `20${raw.replace(/^0+/, '')}`;
  return `https://wa.me/${phone}${message ? `?text=${encodeURIComponent(message)}` : ''}`;
}

function openCenterDetails(id) {
  const center = LIVE_DATA.centers.find(item => String(item.id) === String(id));
  if (!center) return;
  const root = document.getElementById('centerDetailContent');
  const modal = document.getElementById('centerDetailModal');
  if (!root || !modal) return;
  const title = esc(center.name || 'سنتر تدريبي');
  const cover = center.cover_image ? `<img class="center-detail-cover" src="${esc(center.cover_image)}" alt="${title}">` : '';
  const media = (center.media || []).map(item => {
    const path = esc(item.file_path || '');
    const label = esc(item.title || item.original_name || 'ملف السنتر');
    return item.media_type === 'video'
      ? `<div class="center-media-item"><h4>${label}</h4><video controls preload="metadata" src="${path}"></video></div>`
      : `<a class="center-file-link" href="${path}" target="_blank" rel="noopener">📄 ${label}</a>`;
  }).join('');
  const slots = (center.slots || []).map(slot => {
    const date = esc(slot.booking_date || '');
    const time = [slot.start_time, slot.end_time].filter(Boolean).map(esc).join(' - ');
    const slotTitle = esc(slot.title || 'موعد متاح');
    const message = `أرغب في الحجز في ${center.name} - ${slot.title || 'موعد متاح'} (${slot.booking_date || ''} ${time})`;
    return `<div class="center-slot"><div><strong>${slotTitle}</strong><span>${date}${time ? `  —  ${time}` : ''}${slot.capacity ? `  —  الأماكن: ${Number(slot.capacity)}` : ''}</span></div><a class="btn btn-primary btn-sm" href="${esc(centerWhatsAppLink(center, message))}" target="_blank" rel="noopener">احجز الموعد</a></div>`;
  }).join('');
  const address = center.address ? `<p class="center-detail-address">📍 ${esc(center.address)}${center.map_url ? ` <a href="${esc(center.map_url)}" target="_blank" rel="noopener">عرض الخريطة</a>` : ''}</p>` : '';
  const message = `أرغب في الحجز والاستفسار عن سنتر: ${center.name || ''}`;
  root.innerHTML = `${cover}<div class="center-detail-body"><span class="section-eyebrow">التدريب الحضوري</span><h2 id="centerDetailTitle">${title}</h2>${address}<p>${esc(center.description || 'تواصل معنا لمعرفة تفاصيل التدريب والحجز.')}</p><div class="center-detail-actions"><a class="btn btn-primary" href="${esc(centerWhatsAppLink(center, message))}" target="_blank" rel="noopener">احجز الآن</a><a class="btn btn-whatsapp" href="${esc(centerWhatsAppLink(center, message))}" target="_blank" rel="noopener">${whatsappIcon()} واتساب</a></div>${slots ? `<h3>مواعيد الحجز المتاحة</h3><div class="center-slots">${slots}</div>` : ''}${media ? `<h3>محتوى السنتر</h3><div class="center-media-list">${media}</div>` : ''}</div>`;
  modal.hidden = false;
  modal.setAttribute('aria-hidden', 'false');
  document.body.classList.add('center-modal-open');
}

function renderHomeCenters() {
  const root = document.getElementById('homeCenters');
  if (!root) return;
  const labels = catalogActionLabels();
  if (!LIVE_DATA.centers.length) {
    root.innerHTML = '<div class="center-loading">لا توجد سناتر متاحة للحجز حاليًا.</div>';
    return;
  }
  root.innerHTML = LIVE_DATA.centers.map(center => {
    const name = esc(center.name || 'سنتر تدريبي');
    const address = esc(center.address || '');
    const image = center.cover_image ? `<img src="${esc(center.cover_image)}" alt="${name}" loading="lazy">` : '<div class="center-card-placeholder">🏥</div>';
    const message = `أرغب في الحجز والاستفسار عن سنتر: ${center.name || ''}`;
    return `<article class="center-card">${image}<div class="center-card-body"><h3>${name}</h3>${address ? `<p>📍 ${address}</p>` : ''}<p class="center-card-description">${esc(center.description || 'تدريب حضوري ومواعيد حجز متاحة.')}</p><div class="center-card-actions"><button class="btn btn-primary btn-sm" type="button" onclick="openCenterDetails('${center.id}')">${labels.book}</button><a class="btn btn-whatsapp btn-sm" href="${esc(centerWhatsAppLink(center, message))}" target="_blank" rel="noopener">${whatsappIcon()} ${labels.whatsapp}</a><button class="btn btn-outline btn-sm center-content-button" type="button" onclick="openCenterDetails('${center.id}')">📖 عرض المحتوى</button></div></div></article>`;
  }).join('');
}

async function fetchOfflineCenters() {
  try {
    const response = await fetch('api/public/offline-centers.php', { headers: { Accept: 'application/json' }, cache: 'no-store' });
    if (!response.ok) throw new Error('Center list unavailable');
    const data = await response.json();
    if (!data?.success || !Array.isArray(data.centers)) throw new Error('Invalid center response');
    LIVE_DATA.centers = data.centers;
    renderHomeCenters();
  } catch (error) {
    const root = document.getElementById('homeCenters');
    if (root) root.innerHTML = '<div class="center-loading">تعذر تحميل السناتر حاليًا. حاول مرة أخرى لاحقًا.</div>';
    console.warn('Could not load offline centers:', error);
  }
}

function closeCenterDetails() {
  const modal = document.getElementById('centerDetailModal');
  if (!modal) return;
  modal.hidden = true;
  modal.setAttribute('aria-hidden', 'true');
  document.body.classList.remove('center-modal-open');
  const videos = modal.querySelectorAll('video');
  videos.forEach(video => { video.pause(); video.removeAttribute('src'); video.load(); });
}

