function filterCoursesByInstructor(name) {
  navigate('courses');
  const searchInput = document.getElementById('courseSearch');
  if (searchInput) {
    searchInput.value = name.replace('د. ', '').trim();
    renderCourses();
  }
}

function copyCouponCode(code, btn) {
  navigator.clipboard.writeText(code).then(() => {
    toast(t('copied') + ' (' + code + ')', 'success');
    if (btn) {
      const origText = btn.innerHTML;
      btn.innerHTML = '✔ ' + t('copied');
      setTimeout(() => { btn.innerHTML = origText; }, 2000);
    }
  }).catch(() => {
    toast(code, 'info');
  });
}

function renderOffers() {
  const coupons = (LIVE_DATA.offers && LIVE_DATA.offers.coupons) || [];
  const discountedCourses = COURSES.filter(c => c.has_discount);
  const discountedBooks = BOOKS.filter(b => b.has_discount);

  // Render Coupon Banner
  const couponHtml = coupons.length > 0 ? `
    <div class="coupon-banner-info">
      <div class="coupon-icon-circle">🎁</div>
      <div>
        <h4 class="coupon-banner-title">${STATE.lang==='ar' ? 'كوبونات خصم إضافية حصرية!' : 'Exclusive Extra Discount Coupons!'}</h4>
        <p class="coupon-banner-desc">${t('coupon_hint')}</p>
      </div>
    </div>
    <div style="display:flex;align-items:center;gap:12px;flex-wrap:wrap;">
      ${coupons.map(cp => `
        <div class="coupon-code-badge">
          <span>${cp.code}</span>
          <button class="coupon-copy-btn" onclick="copyCouponCode('${cp.code}', this)">
            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg>
            <span>${t('copy_code')} (${Math.round(cp.discount_value)}%)</span>
          </button>
        </div>
      `).join('')}
    </div>
  ` : '';

  const cb = document.getElementById('couponBanner');
  if (cb) {
    cb.innerHTML = couponHtml;
    cb.style.display = couponHtml ? 'flex' : 'none';
  }
  const acb = document.getElementById('allOffersCouponBanner');
  if (acb) {
    acb.innerHTML = couponHtml;
    acb.style.display = couponHtml ? 'flex' : 'none';
  }

  // Combine discounted courses and discounted books
  const offerCardsHtml = [
    ...discountedCourses.map(courseCard),
    ...discountedBooks.map(bookCard)
  ].join('');

  const emptyOffers = `<div class="empty-state"><h3>${STATE.lang==='ar'?'لا توجد عروض حالياً':'No active offers right now'}</h3></div>`;
  const og = document.getElementById('offersGrid');
  if (og) og.innerHTML = offerCardsHtml || emptyOffers;

  const aog = document.getElementById('allOffersGrid');
  if (aog) aog.innerHTML = offerCardsHtml || emptyOffers;
}

function renderTopCourses(){
if (document.getElementById('topCourses')) document.getElementById('topCourses').innerHTML = COURSES.slice(0,4).map(courseCard).join('');
}
function renderTopBooks(){
if (document.getElementById('topBooks')) document.getElementById('topBooks').innerHTML = BOOKS.slice(0,4).map(bookCard).join('');
}
function renderCourses(){
const q = (document.getElementById('courseSearch')?.value || '').toLowerCase();
const lvl = document.getElementById('courseLevel')?.value || '';
const list = COURSES.filter(c=>{
const match = (c.title_ar+c.title_en+c.desc_ar+c.desc_en).toLowerCase().includes(q);
const lvlMatch = !lvl || c.level===lvl;
return match && lvlMatch;
});
const el = document.getElementById('allCourses');
if(!list.length){ el.innerHTML = emptyState('search'); return; }
el.innerHTML = list.map(courseCard).join('');
}
function renderBooks(){
const q = (document.getElementById('bookSearch')?.value || '').toLowerCase();
const list = BOOKS.filter(b=>(b.title_ar+b.title_en+b.desc_ar+b.desc_en).toLowerCase().includes(q));
const el = document.getElementById('allBooks');
if(!list.length){ el.innerHTML = emptyState('search'); return; }
el.innerHTML = list.map(bookCard).join('');
}
function emptyState(type){
const msg = type==='search' ? (STATE.lang==='ar'?'لا توجد نتائج':'No results found') : t('cart_empty');
const desc = type==='search' ? (STATE.lang==='ar'?'جرّب كلمة مختلفة':'Try a different keyword') : t('cart_empty_desc');
return `<div class="empty-state"> <svg width="56" height="56" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg> <h3>${msg}</h3><p>${desc}</p> ${type==='cart' ?`<button class="btn btn-primary" onclick="navigate('courses')">${t('cart_browse')}</button>` : ''}
</div>`;
}

