/* =========================================================
AUTH
========================================================= */
document.querySelectorAll('.role-opt[data-role]').forEach(b=>{
b.onclick = ()=>{
document.querySelectorAll('.role-opt[data-role]').forEach(x=>x.classList.remove('active'));
b.classList.add('active');
document.getElementById('specField').style.display = b.dataset.role==='instructor' ? 'block' : 'none';
};
});

function doLogin(e){
e.preventDefault();
const f = e.target;
const email = f.email.value.trim().toLowerCase();
const pass = f.password.value;
const user = STATE.users.find(u=>u.email.toLowerCase()===email && u.password===pass);
if(!user){ toast(t('m_login_fail'),'error'); return; }
STATE.currentUser = user; saveUser();
toast(t('m_login_ok'),'success');
if(user.role==='admin') navigate('admin-dash');
else if(user.role==='instructor') navigate('instructor-dash');
else navigate('student-dash');
}

function doRegister(e){
e.preventDefault();
const f = e.target;
const role = document.querySelector('.role-opt[data-role].active').dataset.role;
const data = {
id:'u_'+Date.now(),
role,
name:f.name.value.trim(),
email:f.email.value.trim().toLowerCase(),
phone:f.phone.value.trim(),
password:f.password.value,
verified:true,
approved: role==='instructor' ? false : true
};
if(role==='instructor') data.specialty = f.specialty.value.trim();
if(STATE.users.find(u=>u.email===data.email)){ toast(t('m_register_exist'),'error'); return; }
STATE.users.push(data); saveUsers();
STATE.currentUser = data; saveUser();
toast(t('m_register_ok'),'success');
if(role==='instructor') navigate('instructor-dash');
else navigate('student-dash');
}

function logout(){
STATE.currentUser = null;
localStorage.removeItem('nbc_user');
toast(t('m_logout_ok'),'info');
navigate('home');
}

