function resetInstructorCourseForm(){ editingInstructorCourseId=null; renderInstructorDash(); }
function editInstructorCourse(id){ editingInstructorCourseId=id; instructorTab='course-manager'; renderInstructorDash(); }
function saveInstructorCourse(e){
e.preventDefault();
const form=e.target, u=STATE.currentUser;
const data={
title_ar:form.title_ar.value.trim(), title_en:form.title_en.value.trim(),
desc_ar:form.desc_ar.value.trim(), desc_en:form.desc_en.value.trim(),
duration:form.duration.value.trim(), duration_en:form.duration_en.value.trim(),
lessons:Math.max(1,Math.min(500,Number(form.lessons.value)||1)), level:form.level.value,
icon:'book', goals_ar:[], goals_en:[], curriculum_ar:[], curriculum_en:[]
};
if(!data.title_ar||!data.title_en||!data.desc_ar||!data.desc_en){toast(instructorText('اكمل البيانات المطلوبة','Please complete the required fields'),'error');return;}
if(editingInstructorCourseId){
const course=COURSES.find(c=>c.id===editingInstructorCourseId);
if(course && course.instructorId===u.id) Object.assign(course,data);
}else{
const id='ic_'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const course={...data,id,instructorId:u.id,createdAt:new Date().toISOString()};
COURSES.push(course);
u.courses=Array.from(new Set([...(u.courses||[]),id]));
}
persistCustomCourses(); saveUsers(); saveUser();
editingInstructorCourseId=null;
toast(instructorText('تم حفظ بيانات الكورس محليًا','Course saved locally'),'success');
renderInstructorDash();
}
function deleteInstructorCourse(id){
const course=COURSES.find(c=>c.id===id);
if(!course || course.instructorId!==STATE.currentUser?.id) return;
if(!confirm(instructorText('هل أنت متأكد من حذف الكورس؟','Delete this course?'))) return;
COURSES=COURSES.filter(c=>c.id!==id);
STATE.currentUser.courses=(STATE.currentUser.courses||[]).filter(x=>x!==id);
saveUsers();saveUser();persistCustomCourses();
editingInstructorCourseId=null;
toast(instructorText('تم حذف الكورس','Course deleted'),'success');
renderInstructorDash();
}
function selectInstructorCourse(id){window.instructorSelectedCourseId=id;renderInstructorDash();}
function localLessonMediaDb(){return new Promise((resolve,reject)=>{const req=indexedDB.open('nbc_local_lesson_media',1);req.onupgradeneeded=()=>req.result.createObjectStore('videos');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
async function storeLocalLessonVideo(key,file){const db=await localLessonMediaDb();return new Promise((resolve,reject)=>{const tx=db.transaction('videos','readwrite');tx.objectStore('videos').put(file,key);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
async function deleteLocalLessonVideo(key){if(!key)return;const db=await localLessonMediaDb();return new Promise(resolve=>{const tx=db.transaction('videos','readwrite');tx.objectStore('videos').delete(key);tx.oncomplete=resolve;tx.onerror=resolve;});}
async function playInstructorLesson(key){try{const db=await localLessonMediaDb();const blob=await new Promise((resolve,reject)=>{const req=db.transaction('videos').objectStore('videos').get(key);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});if(!blob)throw Error('تعذر العثور على ملف الفيديو المحفوظ.');const old=document.getElementById('localLessonVideoModal');if(old)old.remove();const modal=document.createElement('div');modal.id='localLessonVideoModal';modal.style='position:fixed;inset:0;z-index:99999;background:#000d;display:grid;place-items:center;padding:20px';modal.innerHTML='<button style="position:absolute;top:15px;right:20px;font-size:30px;color:white;background:none;border:0;cursor:pointer" aria-label="إغلاق">×</button><video controls autoplay playsinline style="width:min(100%,1000px);max-height:85vh;background:#000"></video>';const player=modal.querySelector('video');player.src=URL.createObjectURL(blob);modal.querySelector('button').onclick=()=>{player.pause();URL.revokeObjectURL(player.src);modal.remove();};modal.onclick=e=>{if(e.target===modal)modal.querySelector('button').click();};document.body.append(modal);}catch(err){toast(err.message||'تعذر تشغيل الفيديو','error');}}
async function addInstructorLesson(e,courseId){
e.preventDefault();
const course=COURSES.find(c=>c.id===courseId);
if(!course || !getInstructorCourses().some(c=>c.id===courseId)) return;
const form=e.target, lessons=getCourseLessons(course), file=form.videoFile.files?.[0];
if(file && (file.type!=='video/mp4'||file.size>35*1024*1024)){toast(instructorText('ارفع فيديو MP4 لا يتجاوز 35 ميجابايت','Choose an MP4 video up to 35 MB'),'error');return;}
const lessonId=`${courseId}_l_${Date.now()}`, mediaKey=file?`lesson_${lessonId}`:'';
if(file)try{await storeLocalLessonVideo(mediaKey,file);}catch(_){toast(instructorText('تعذر حفظ الفيديو في مساحة المتصفح','Could not save video in browser storage'),'error');return;}
lessons.push({id:lessonId,title:form.lessonTitle.value.trim(),description:'',videoUrl:'',mediaKey,order:lessons.length+1,status:'draft'});
saveCourseLessons(courseId,lessons);
course.lessons=lessons.length;
window.instructorSelectedCourseId=courseId;
toast(instructorText('تمت إضافة الدرس محليًا','Lesson added locally'),'success');
renderInstructorDash();
}
function deleteInstructorLesson(courseId,lessonId){
const course=COURSES.find(c=>c.id===courseId);
if(!course || !getInstructorCourses().some(c=>c.id===courseId)) return;
const existing=getCourseLessons(course), removed=existing.find(l=>l.id===lessonId);if(removed?.mediaKey)deleteLocalLessonVideo(removed.mediaKey);
const lessons=existing.filter(l=>l.id!==lessonId).map((l,i)=>({...l,order:i+1}));
saveCourseLessons(courseId,lessons);course.lessons=lessons.length;
window.instructorSelectedCourseId=courseId;renderInstructorDash();
}
function setInstructorTab(id){
if(id==='logout'){ logoutUser(); return; }
instructorTab=id; renderInstructorDash();
}

