function exportCSV(){
if(!STATE.orders.length){ toast(STATE.lang==='ar'?'لا توجد بيانات':'No data','error'); return; }
const headers = ['Order ID','User','Total','Method','Reference','Status','Date'];
const rows = STATE.orders.map(o=>{
const u = STATE.users.find(x=>x.id===o.userId);
return [o.id, u?u.name:'', o.total, o.method, o.ref, o.status, new Date(o.date).toISOString()];
});
const csv = [headers, ...rows].map(r=>r.map(c=>`"${String(c).replace(/"/g,'""')}"`).join(',')).join('\n');
const blob = new Blob([csv], {type:'text/csv;charset=utf-8'});
const url = URL.createObjectURL(blob);
const a = document.createElement('a');
a.href = url; a.download = 'orders-'+Date.now()+'.csv'; a.click();
URL.revokeObjectURL(url);
toast(STATE.lang==='ar'?'تم التصدير':'Exported','success');
}

