/* =========================================================
INIT & FIX LOADING HANG
========================================================= */
function dismissLoader() {
  const loader = document.getElementById('loader');
  if (loader) {
    loader.classList.add('hide');
    loader.style.opacity = '0';
    loader.style.pointerEvents = 'none';
    setTimeout(() => { if (loader) loader.style.display = 'none'; }, 250);
  }
}

function applyLivePlatformSettings(settings) {
  if (!settings) return;
  const logo = /^uploads\/platform\/logo-[a-f0-9]{40}\.(jpg|png|webp)$/i.test(settings.platform_logo || '') ? settings.platform_logo : '';
  document.querySelectorAll('.brand-mark').forEach(mark => {
    if (logo) {
      const img = document.createElement('img');
      img.src = logo; img.alt = settings.academy_name_ar || settings.academy_name || 'شعار المنصة';
      img.style.cssText = 'width:100%;height:100%;object-fit:contain;border-radius:inherit';
      mark.replaceChildren(img);
      mark.classList.add('has-platform-logo');
    } else if (mark.classList.contains('has-platform-logo')) {
      mark.classList.remove('has-platform-logo');
      mark.innerHTML = '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v6M9 5h6"/><path d="M20 12a8 8 0 1 1-16 0 8 8 0 0 1 16 0z"/><path d="M12 8v8M8 12h8"/></svg>';
    }
  });
  window.platformIntroVideo = /^uploads\/platform\/intro-video-[a-f0-9]+\.mp4$/i.test(settings.hero_video_url || '') ? settings.hero_video_url : '';
  if (window.applyMedicalThemeSettings) window.applyMedicalThemeSettings(settings);
  if (settings.contact_phone) {
    STATE.settings.contactPhone = settings.contact_phone;
  }
  if (settings.whatsapp_number) {
    const rawNum = settings.whatsapp_number.replace(/\D/g, '');
    const intlNum = rawNum.startsWith('20') ? rawNum : ('20' + rawNum.replace(/^0+/, ''));
    document.querySelectorAll('a[href*="wa.me"]').forEach(a => {
      const origQuery = a.getAttribute('href').split('?')[1] || '';
      a.href = `https://wa.me/${intlNum}${origQuery ? '?' + origQuery : ''}`;
    });
  }
  if (settings.payment_vodafone) {
    STATE.settings.payVodafone = settings.payment_vodafone;
    const el = document.getElementById('payNum');
    if (el) el.textContent = settings.payment_vodafone;
  }
  if (settings.founder_name) {
    document.querySelectorAll('[data-i18n="hero_author"], [data-i18n="ins_name"]').forEach(el => {
      el.textContent = settings.founder_name;
    });
  }
  if (settings.founder_title) {
    document.querySelectorAll('[data-i18n="hero_author_role"]').forEach(el => {
      el.textContent = settings.founder_title;
    });
  }
}

function applyLiveStats(stats) {
  if (!stats) return;
  const slc = document.getElementById('statLiveCourses');
  if (slc && Number.isFinite(Number(stats.courses_count))) slc.textContent = Number(stats.courses_count).toLocaleString(STATE.lang === 'en' ? 'en-US' : 'ar-EG');
  const slb = document.getElementById('statLiveBooks');
  if (slb && Number.isFinite(Number(stats.books_count))) slb.textContent = Number(stats.books_count).toLocaleString(STATE.lang === 'en' ? 'en-US' : 'ar-EG');

  const statNumbers = document.querySelectorAll('.stat-counter-num');
  if (statNumbers.length >= 4) {
    const locale = STATE.lang === 'en' ? 'en-US' : 'ar-EG';
    if (Number.isFinite(Number(stats.students))) statNumbers[0].textContent = Number(stats.students).toLocaleString(locale);
    if (Number.isFinite(Number(stats.courses_count))) statNumbers[1].textContent = Number(stats.courses_count).toLocaleString(locale);
    if (Number.isFinite(Number(stats.books_count))) statNumbers[2].textContent = Number(stats.books_count).toLocaleString(locale);
    if (Number.isFinite(Number(stats.enrollments))) statNumbers[3].textContent = Number(stats.enrollments).toLocaleString(locale);
  }
}

async function fetchLiveData() {
  try {
    const res = await fetch('api/public/landing.php', {
      headers: { 'Accept': 'application/json' }
    });
    if (res.ok) {
      const data = await res.json();
      if (data && data.success) {
        LIVE_DATA.loaded = true;
        LIVE_DATA.courses = data.courses || [];
        LIVE_DATA.books = data.books || [];
        LIVE_DATA.instructors = data.instructors || [];
        LIVE_DATA.home_slider = data.home_slider || [];
        LIVE_DATA.offers = data.offers || { courses: [], books: [], coupons: [] };
        LIVE_DATA.settings = data.settings || {};
        LIVE_DATA.stats = data.stats || {};

        if (LIVE_DATA.courses.length > 0) {
          COURSES = LIVE_DATA.courses.map(mapApiCourseToAppCourse);
        }
        if (LIVE_DATA.books.length > 0) {
          BOOKS = LIVE_DATA.books.map(mapApiBookToAppBook);
        }

        applyLivePlatformSettings(data.settings);
        applyLiveStats(data.stats);

        // Re-render UI with live data
        renderAll();
      }
    }
  } catch (err) {
    console.warn('Could not load live landing data, using offline fallbacks:', err);
  }
}

async function fetchHomeSlider() {
  try {
    const response = await fetch('api/public/home-slider.php', { headers: { Accept: 'application/json' }, cache: 'no-store' });
    if (!response.ok) return;
    const data = await response.json();
    if (!data?.success || !Array.isArray(data.slides)) return;
    LIVE_DATA.home_slider = data.slides;
    renderHomeMedicalSlider();
  } catch (error) {
    console.warn('Could not load homepage slider:', error);
  }
}

async function fetchFounderPhotos() {
  try {
    const response = await fetch('api/public/founder-photos.php', { headers: { Accept: 'application/json' }, cache: 'no-store' });
    if (!response.ok) return;
    const data = await response.json();
    if (!data?.success || !Array.isArray(data.photos)) return;
    LIVE_DATA.founder_photos = data.photos;
    renderFounderPhotos();
  } catch (error) {
    console.warn('Could not load founder photos:', error);
  }
}

function renderAll(){
  try { applyI18n(); } catch(e) { console.warn('applyI18n err:', e); }
  try { renderHomeMedicalSlider(); } catch(e) { console.warn('home slider err:', e); }
  try { renderFounderPhotos(); } catch(e) { console.warn('founder photos err:', e); }
  try { renderFeatures(); } catch(e) { console.warn('renderFeatures err:', e); }
  try { renderOffers(); } catch(e) { console.warn('renderOffers err:', e); }
  try { renderTopCourses(); } catch(e) { console.warn('renderTopCourses err:', e); }
  try { renderTopBooks(); } catch(e) { console.warn('renderTopBooks err:', e); }
  try { renderHomeCenters(); } catch(e) { console.warn('renderHomeCenters err:', e); }
  try { renderInstructors(); } catch(e) { console.warn('renderInstructors err:', e); }
  try { renderTestimonials(); } catch(e) { console.warn('renderTestimonials err:', e); }
  try { renderFAQ('faqList'); } catch(e) { console.warn('renderFAQ err:', e); }
  try { updateCartBadge(); } catch(e) { console.warn('updateCartBadge err:', e); }
  try {
    if(STATE.currentRoute==='courses') renderCourses();
    if(STATE.currentRoute==='books') renderBooks();
    if(STATE.currentRoute==='offers') renderOffers();
    if(STATE.currentRoute==='instructors') renderInstructors();
    if(STATE.currentRoute==='course-detail') renderCourseDetail();
    if(STATE.currentRoute==='book-detail') renderBookDetail();
    if(STATE.currentRoute==='cart') renderCart();
  } catch(e) { console.warn('route render err:', e); }
}

